import csv
import io
from decimal import Decimal, ROUND_HALF_UP

def summarize_ledger(csv_text):
    totals = {}
    f = io.StringIO(csv_text.strip())
    reader = csv.reader(f)

    try:
        header = next(reader)
    except StopIteration:
        return {}

    # The docstring says "Columns are date,category,description,amount."
    # It also says "A row that does not have exactly four fields ... is not a data row and must be skipped"

    for row in reader:
        if len(row) != 4:
            continue

        date, category, description, amount_str = row

        category = category.strip().lower()
        amount_str = amount_str.strip()

        if not amount_str:
            continue

        # Handle accounting parentheses (45.00) -> -45.00
        if amount_str.startswith('(') and amount_str.endswith(')'):
            amount_str = '-' + amount_str[1:-1]

        # Remove currency symbols and thousands separators
        # The docstring says: "Amounts may be quoted, may use $, EUR (€), or GBP (£) symbols,
        # thousands separators, and may have a third decimal place"
        # We can just strip the symbols we know about.
        for symbol in ('$', '€', '£'):
            amount_str = amount_str.replace(symbol, '')

        amount_str = amount_str.replace(',', '')

        try:
            amount = Decimal(amount_str)
            totals[category] = totals.get(category, Decimal('0')) + amount
        except:
            # If amount is not a valid number, skip
            continue

    # Return rounded results
    return {k: float(v.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)) for k, v in totals.items()}
