import csv
import io
from decimal import Decimal, ROUND_HALF_UP

def summarize_ledger(csv_text):
    """Total the amount column per category from a ledger export.

    Returns {category: total} with each total rounded to 2 decimals,
    using round-half-up (accounting convention), not Python's default
    round-half-to-even.

    Columns are date,category,description,amount. Category keys are
    lowercase with surrounding whitespace stripped. The description
    field may contain commas and RFC4180-escaped internal quotes
    (a doubled "" represents one literal ").

    Amounts may be quoted, may use $, EUR (€), or GBP (£) symbols,
    thousands separators, and may have a third decimal place (a sub-cent
    remainder from currency conversion). A negative amount is written
    either in accounting parentheses, e.g. (45.00), or with a leading
    minus sign.

    Rows with a missing or empty amount are pre-filtered, as are blank lines.
    A row that does not have exactly four fields once quoting is
    accounted for (e.g. a trailing report/footer line) is not a data
    row and must be skipped without raising an error.
    """
    totals = {}
    f = io.StringIO(csv_text.strip())
    reader = csv.reader(f)

    try:
        next(reader)  # Skip header
    except StopIteration:
        return {}

    for row in reader:
        if len(row) != 4:
            continue

        _, category, _, amount_str = row

        category = category.strip().lower()
        amount_str = amountly_str_clean(amount_str)

        if not amount_str:
            continue

        try:
            # Handle accounting parentheses (45.00) -> -45.00
            if amount_str.startswith('(') and amount_str.endswith(')'):
                amount_str = '-' + amount_str[1:-1]

            # Remove currency symbols
            for symbol in ('$', '€', '£'):
                amount_str = amount_str.replace(symbol, '')

            # Remove thousands separator
            amount_str = amount_str.replace(',', '')

            amount = Decimal(amount_str)
            totals[category] = totals.get(category, Decimal('0')) + amount
        except:
            continue

    return {k: float(v.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)) for k, v in totals.items()}

def amountly_str_clean(s):
    return s.strip()
